add(s,'i0','There are three types of cubic lattices.','مکعبی جالیوں کی تین اقسام ہیں۔','د مکعبي جالیو درې ډولونه شته.')
head(s,'i-h','i. Simple Cubic Lattice (Cubic P – type lattice)','i. سادہ مکعبی جالی (مکعبی P قسم کی جالی)','i. ساده مکعبي جالۍ (مکعبي P ډوله جالۍ)')
add(s,'i1','In this type of cubic lattice, the points are only at the corners of each unit cell. They have maximum vacant space and are rarely found in nature. There are eight corners in a simple cubic system ad each point occupying a corner of the cell is shared by the eight unit cell as shown in figure 6.11(a).','اس قسم کی مکعبی جالی میں نقاط صرف ہر اکائی خانے کے کونوں پر ہوتے ہیں۔ ان میں زیادہ سے زیادہ خالی جگہ ہوتی ہے اور یہ قدرت میں شاذ و نادر ملتی ہیں۔ سادہ مکعبی نظام میں آٹھ کونے ہوتے ہیں اور خانے کے کونے پر موجود ہر نقطہ آٹھ اکائی خانوں میں مشترک ہوتا ہے جیسا کہ شکل 6.11(a) میں دکھایا گیا ہے۔','په دې ډول مکعبي جالۍ کې ټکي یوازې د هرې واحد حجرې په کونجونو کې وي. دوی تر ټولو ډېره تشه ځای لري او په طبیعت کې لږ موندل کېږي. په ساده مکعبي سیستم کې اته کونجونه شته او د حجرې په کونج کې هر ټکی د اتو واحد حجرو ترمنځ ګډ دی لکه څنګه چې په 6.11(a) شکل کې ښودل شوي.',printedMisprint='ad (and)')
head(s,'ii-h','ii. Body Centered Cubic (bcc) Lattice (Cubic I – type lattice)','ii. جسم مرکوز مکعبی (bcc) جالی (مکعبی I قسم کی جالی)','ii. بدن مرکزي مکعبي (bcc) جالۍ (مکعبي I ډوله جالۍ)')
add(s,'ii1','In body centered cubic (bcc) lattice, each unit cell has one point (particle) at the center of the cube in addition to the points at the corners. In this case particles are packed more efficiently than in the simple cubic lattice. Each point in the centre of the cell is part of only one unit cell as shown in figure 6.11 (b).','جسم مرکوز مکعبی (bcc) جالی میں ہر اکائی خانے میں کونوں کے نقاط کے علاوہ مکعب کے مرکز میں ایک نقطہ (ذرہ) ہوتا ہے۔ اس صورت میں ذرات سادہ مکعبی جالی کے مقابلے میں زیادہ مؤثر طریقے سے بھرے ہوتے ہیں۔ خانے کے مرکز کا ہر نقطہ صرف ایک اکائی خانے کا حصہ ہوتا ہے جیسا کہ شکل 6.11 (b) میں دکھایا گیا ہے۔','په بدن مرکزي مکعبي (bcc) جالۍ کې هره واحد حجره د کونجونو له ټکو سربېره د مکعب په مرکز کې یو ټکی (ذره) لري. په دې حالت کې ذرات د ساده مکعبي جالۍ په پرتله ډېر اغېزمن ډول ډک شوي دي. د حجرې په مرکز کې هر ټکی یوازې د یوې واحد حجرې برخه ده لکه څنګه چې په 6.11 (b) شکل کې ښودل شوي.')
head(s,'iii-h','iii. Face Centered Cubic (fcc) Lattice (Cubic F – type lattice)','iii. رخ مرکوز مکعبی (fcc) جالی (مکعبی F قسم کی جالی)','iii. مخ مرکزي مکعبي (fcc) جالۍ (مکعبي F ډوله جالۍ)')
add(s,'iii1','They have one point at each of the six faces of the cube, in addition to the points at the corners. Maximum space is occupied by the particles in this case. Here each point at the corner is shared by eight unit cells and the point at the centre of each face is shared by two unit cells figure 6.11 (c).','ان میں کونوں کے نقاط کے علاوہ مکعب کے چھ رخوں میں سے ہر ایک پر ایک نقطہ ہوتا ہے۔ اس صورت میں ذرات سب سے زیادہ جگہ گھیرتے ہیں۔ یہاں کونے کا ہر نقطہ آٹھ اکائی خانوں میں مشترک ہوتا ہے اور ہر رخ کے مرکز کا نقطہ دو اکائی خانوں میں مشترک ہوتا ہے شکل 6.11 (c)۔','دوی د کونجونو له ټکو سربېره د مکعب په هر یو شپږو مخونو کې یو ټکی لري. په دې حالت کې ذرات تر ټولو ډېر ځای نیسي. دلته په کونج کې هر ټکی د اتو واحد حجرو ترمنځ ګډ دی او د هر مخ په مرکز کې ټکی د دوو واحد حجرو ترمنځ ګډ دی، 6.11 (c) شکل.')
def cube3(x,y,w,dots):
    d=w*0.35
    o=f'<g fill="none" stroke="#222" stroke-width="2"><rect x="{x}" y="{y+d}" width="{w}" height="{w}"/><rect x="{x+d}" y="{y}" width="{w}" height="{w}"/><path d="M{x} {y+d} L{x+d} {y} M{x+w} {y+d} L{x+w+d} {y} M{x} {y+d+w} L{x+d} {y+w} M{x+w} {y+d+w} L{x+w+d} {y+w}"/></g>'
    c=[(x,y+d),(x+w,y+d),(x,y+d+w),(x+w,y+d+w),(x+d,y),(x+w+d,y),(x+d,y+w),(x+w+d,y+w)]
    o+=''.join(f'<circle cx="{a}" cy="{b}" r="4.5" fill="#111"/>' for a,b in c)
    if dots=='bcc': o+=f'<circle cx="{x+w/2+d/2}" cy="{y+w/2+d/2}" r="5" fill="#111"/>'
    if dots=='fcc':
        for a,b in [(x+w/2,y+d+w/2),(x+w/2+d,y+w/2),(x+w/2+d/2,y+d/2),(x+w/2+d/2,y+d+w),(x,y+d+w/2),(x+w,y+d+w/2)]:
            o+=f'<circle cx="{a}" cy="{b}" r="4.5" fill="#111"/>'
    return o
def sq(x,y,w,dots):
    o=f'<rect x="{x}" y="{y}" width="{w}" height="{w}" fill="none" stroke="#222" stroke-width="2"/>'+''.join(f'<circle cx="{a}" cy="{b}" r="4.5" fill="#111"/>' for a,b in [(x,y),(x+w,y),(x,y+w),(x+w,y+w)])
    if dots=='bcc': o+=f'<circle cx="{x+w/2}" cy="{y+w/2}" r="5" fill="#fff" stroke="#111"/>'
    if dots=='fcc': o+=f'<circle cx="{x+w/2}" cy="{y+w/2}" r="5" fill="#111"/>'+''.join(f'<circle cx="{a}" cy="{b}" r="4.5" fill="#fff" stroke="#111"/>' for a,b in [(x+w/2,y),(x+w/2,y+w),(x,y+w/2),(x+w,y+w/2)])
    return o
body=cube3(20,10,100,'sc')+cube3(210,10,100,'bcc')+cube3(400,10,100,'fcc')+sq(30,200,90,'sc')+sq(220,200,90,'bcc')+sq(410,200,90,'fcc')+T(70,170,'Simple Cubic Lattice',11,'middle',700)+T(260,170,'Body Centered Cubic',11,'middle',700)+T(450,170,'Free Centered Cubic',11,'middle',700)+T(75,315,'(a)',10)+T(265,315,'(b)',10)+T(455,315,'(c)',10)+'<path d="M165 10 V310 M355 10 V310" stroke="#111" stroke-dasharray="4 4"/>'+T(275,340,'Figure 6.11 (a), (b), (c) Three Cubic Units Cells',13,'middle',700,'#a02040')
